public class Main {
    static void setAge(int age) {
        if (age < 0) {
            throw new IllegalArgumentException("negative");
        }
        System.out.println("Age set to " + age);
    }

    public static void main(String[] args) {
        try {
            setAge(30);
            setAge(-1);
        } catch (IllegalArgumentException e) {
            System.out.println("Invalid age");
        }
    }
}
